/** The field entity's registry entry (see src/graph/). */
import { asNamedRef, namedFactoryEntry } from "../../catalog/render-helpers.js";
import { NO_LIFECYCLE } from "../../graph/types.js";
import { FIELD_SUB_TYPES } from "./types.js";
export const FIELD_DATA_RESOURCE_TYPE = "elementum_field";
export const fieldModule = {
    kind: "field",
    stream: { role: "streamMember" },
    authoring: { unit: "inline", bag: "fields" },
    parents: [
        { parent: "app", child: "field" },
        { parent: "element", child: "field" },
    ],
    resource: {
        shape: "subTypes",
        rows: FIELD_SUB_TYPES.map((t) => ({
            key: t.typeKey,
            resourceType: t.resourceType,
            implemented: t.implemented === true,
            authoringType: t.authoringType,
        })),
    },
    // Foreign relationship/relation fields are looked up by name under their
    // owning object (`object_id` is recorded by OrgRefLookup.foreignField).
    data: {
        participates: true,
        resourceType: FIELD_DATA_RESOURCE_TYPE,
        lookupAttr: "name",
        referencedByBuild: true,
        referenceLookups: [
            { strategy: "owned", ownerKinds: ["app", "element"], memberAttr: "name" },
            { strategy: "ownerProjection", ownerKind: "table", projectionAttr: "field_ids", memberAttr: "name" },
        ],
    },
    lifecycle: NO_LIFECYCLE,
    canvas: { participates: true, label: "Fields", glyph: "▾", component: "fieldCard" },
    // Inline under app — from-authoring still reads fields from app.ref(); this
    // facet drives render bag name / order (replaces BAG_NAME.field).
    catalog: {
        participates: true,
        refKind: "field",
        catalogBag: "fields",
        renderOrder: 50,
        catalogRoot: "app",
        renderEntry: (args) => {
            const named = asNamedRef(args.ref);
            const field = args.ref;
            const parts = [`fieldType: ${JSON.stringify(field.fieldType)}`];
            if (field.tags !== undefined)
                parts.push(`tags: ${JSON.stringify(field.tags)}`);
            if (field.options !== undefined)
                parts.push(`options: ${JSON.stringify(field.options)}`);
            return namedFactoryEntry({
                factoryName: "fieldRef",
                keyName: args.keyName,
                baseIndent: args.baseIndent,
                name: named.name,
                parent: named.parent,
                extraParts: parts,
            });
        },
        stubRef: (refName, parent) => ({
            __kind: "field",
            refName,
            name: refName,
            parent,
            fieldType: "TEXT",
        }),
        refFromAuthoring: () => undefined,
    },
};
